import{_ as i}from"./chunks/mac-security-settings.DOF-7oNi.js";import{_ as l,o as s,c as e,ae as t}from"./chunks/framework.B6gjLfeO.js";const k=JSON.parse('{"title":"macOSインストール時の一般的な問題 - 「Appが破損している」解決方法","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/mac-installation-issue.md","filePath":"ja/guide/mac-installation-issue.md"}'),p={name:"ja/guide/mac-installation-issue.md"};function o(n,a,r,h,d,c){return s(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="macosインストール時の一般的な問題-「appが破損している」解決方法" tabindex="-1">macOSインストール時の一般的な問題 - 「Appが破損している」解決方法 <a class="header-anchor" href="#macosインストール時の一般的な問題-「appが破損している」解決方法" aria-label="Permalink to &quot;macOSインストール時の一般的な問題 - 「Appが破損している」解決方法&quot;">​</a></h1><p>macOSにOToolsやその他のサードパーティ製アプリケーションをインストールする際、「xxx.appは破損しているため開けません。ごみ箱へ移動させる必要があります」という表示が出ることがあります。これは、通常macOSのセキュリティ設定によるものです。</p><h2 id="なぜこのような現象が起こるのか" tabindex="-1">なぜこのような現象が起こるのか？ <a class="header-anchor" href="#なぜこのような現象が起こるのか" aria-label="Permalink to &quot;なぜこのような現象が起こるのか？&quot;">​</a></h2><p>macOSはWindowsと比較してプログラムに対する制御が非常に厳しく、App Store以外からのアプリインストール時には「xxx.appは破損しています」といった表示が出ることがよくあります。macOS 10.15以降では、署名されていないアプリへの権限がさらに制限され、こうした問題がより頻繁に発生するようになりました。</p><h2 id="解決方法" tabindex="-1">解決方法 <a class="header-anchor" href="#解決方法" aria-label="Permalink to &quot;解決方法&quot;">​</a></h2><h3 id="方法1-「どこからでも」アプリを許可する設定" tabindex="-1">方法1: 「どこからでも」アプリを許可する設定 <a class="header-anchor" href="#方法1-「どこからでも」アプリを許可する設定" aria-label="Permalink to &quot;方法1: 「どこからでも」アプリを許可する設定&quot;">​</a></h3><ol><li>「システム環境設定 -&gt; セキュリティとプライバシー -&gt; 全般」タブを開く</li><li>「どこからでもダウンロードしたアプリを許可」オプションが有効になっているか確認</li><li>有効になっていない場合、左下の小さな鍵アイコンをクリックしてロックを解除し、「どこからでも」を選択</li></ol><p><img src="'+i+'" alt=""></p><p>設定に「どこからでも」オプションが表示されない場合は、ターミナルを開き以下のコマンドを入力してください：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-disable</span></span></code></pre></div><p>コンピュータのログインパスワードを入力し、リターンキーを押します。その後、設定画面に「どこからでも」オプションが表示されます。</p><p>通常、この設定によりアプリは正常にインストールできるようになります。ただし、より新しいmacOSバージョンでは、以下の手順でAppleのゲートキーパーを回避する必要がある場合もあります。</p><h3 id="方法2-appleのゲートキーパー認証を回避" tabindex="-1">方法2: Appleのゲートキーパー認証を回避 <a class="header-anchor" href="#方法2-appleのゲートキーパー認証を回避" aria-label="Permalink to &quot;方法2: Appleのゲートキーパー認証を回避&quot;">​</a></h3><p>方法1でも問題が解決しない場合、以下の手順をお試しください：</p><ol><li>ターミナルを開く</li><li>以下のコマンドを入力しますが、まだリターンキーを押さないでください：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span></span></code></pre></div><ol start="3"><li>FinderのアプリケーションフォルダでOTools.appを見つける</li><li>OTools.appをターミナルウィンドウにドラッグすると、コマンドにアプリのパスが自動的に追加されます</li><li>リターンキーを押し、パスワードを入力すると、アプリを直接実行できるようになります</li></ol><h3 id="方法3-右クリックで開く-初回インストール時におすすめ" tabindex="-1">方法3: 右クリックで開く（初回インストール時におすすめ） <a class="header-anchor" href="#方法3-右クリックで開く-初回インストール時におすすめ" aria-label="Permalink to &quot;方法3: 右クリックで開く（初回インストール時におすすめ）&quot;">​</a></h3><p>初回インストール時は、以下の方法も試せます：</p><ol><li>FinderでOTools.appを探す</li><li>右クリック（またはControlキーを押しながらクリック）</li><li>「開く」を選択</li><li>表示されるセキュリティ警告で「開く」をクリック</li></ol><h2 id="重要な注意事項" tabindex="-1">重要な注意事項 <a class="header-anchor" href="#重要な注意事項" aria-label="Permalink to &quot;重要な注意事項&quot;">​</a></h2><ul><li>OToolsはTauriフレームワークで構築された正当なデスクトップアプリケーションです</li><li>お使いのコンピュータが悪意のあるソフトウェアの影響を受けることはありません</li><li>この問題はアプリケーションではなく、Appleのセキュリティポリシーによって引き起こされます</li></ul>',22)])])}const b=l(p,[["render",o]]);export{k as __pageData,b as default};
